# -*- coding: utf-8 --

from robot.api import logger
from taf.rfrl.cbts.connections.rest_conn_vdu import GenericVDU
from taf.rfrl.cbts.utilities import generic_utils

LOG_HEAD = LOG_END = '*' * 8


class vDUFM(GenericVDU):

    VDU_UNEXPECTED_ACTIVE_ALARMS = ['0010', '0016', '1806', '1868', '4341', '4352', '4383', '4350']

    def get_fault_id_list_from_active_alarms(self, conn_alias='default'):
        fault_id_list = []
        act_alarms = self.vdu.vdu_get_active_alarms(vdu_connection=conn_alias)['alarms']
        logger.info('{} Current active alarms are as below\n{}'.format(LOG_HEAD, act_alarms))
        if act_alarms:
            for alarm in act_alarms:
                fault_id_list.append(alarm['fault_id'])

        return fault_id_list

    @staticmethod
    def add_check_unexpected_active_alarms_list(user_unexpected_alarms):
        if isinstance(type(user_unexpected_alarms), str):
            vDUFM.VDU_UNEXPECTED_ACTIVE_ALARMS.append(user_unexpected_alarms)
        elif isinstance(type(user_unexpected_alarms), list):
            vDUFM.VDU_UNEXPECTED_ACTIVE_ALARMS.extend(user_unexpected_alarms)

    @staticmethod
    def get_unexpected_active_alarm_list():
        return sorted(set(vDUFM.VDU_UNEXPECTED_ACTIVE_ALARMS))

    @staticmethod
    def get_needed_unexpected_active_alarms(user_unexpected_alarms):
        if user_unexpected_alarms:
            list_user_unexpected_alarms = generic_utils.convert_specific_format_string_to_list(user_unexpected_alarms)
            vDUFM.add_check_unexpected_active_alarms_list(list_user_unexpected_alarms)

        check_unexpected_active_alarms = vDUFM.get_unexpected_active_alarm_list()
        return check_unexpected_active_alarms
